30	const BASE_PRICES: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	  staff: 80,
34	  potion: 40,
35	  rune: 25,
36	  moonstone: 25,
37	};
38	
39	// Expressed as integer percent rather than a 1.1 factor: floating-point
40	// multiplication by 1.1 loses exactness (100 * 1.1 === 115.00000000000001),
41	// while scaling by 110 and dividing by 100 stays exact for these prices.
42	const FIRST_CONTRACT_PERCENT = 110;
43	const WHOLE_PERCENT = 100;
44	const CONTRACT_FEE = 5;
45	
46	const BLOCK_SIZE = 3;
47	const BLOCK_PRICE = 60;
48	
49	const COMPONENT_TYPES = ["rune", "moonstone"];
50	
51	const HIGH_ENCHANTMENT_LEVEL = 5;
52	
53	const applyPercent = (amount: number, percent: number): number =>
54	  (amount * percent) / WHOLE_PERCENT;
55	
56	const tablePriceOf = (item: Item): number => BASE_PRICES[item.type];
57	
58	// Risk surcharges stack multiplicatively: each one that applies scales the
59	// running price, so a cursed item is 150 % of the table price.
60	const RISK_SURCHARGES: { applies: (item: Item) => boolean; percent: number }[] =
61	  [
62	    { applies: (item) => item.cursed, percent: 150 },
63	    {
64	      applies: (item) => item.enchantment >= HIGH_ENCHANTMENT_LEVEL,
65	      percent: 130,
66	    },
67	  ];
68	
69	const riskAdjustedPriceOf = (item: Item): number =>
70	  RISK_SURCHARGES.filter((surcharge) => surcharge.applies(item)).reduce(
71	    (price, surcharge) => applyPercent(price, surcharge.percent),
72	    tablePriceOf(item),
73	  );
74	
75	const isComponent = (item: Item): boolean =>
76	  COMPONENT_TYPES.includes(item.type);
77	
78	const allAlike = (items: Item[]): boolean =>
79	  items.every((item) => item.type === items[0].type);
80	
81	// Only alike components combine into blocks — main items (swords, staves,
82	// potions, amulets) are always priced individually, however many there are.
83	const formsBuildingBlocks = (items: Item[]): boolean =>
84	  items.every(isComponent) && allAlike(items);
85	
86	const sumOfItemPrices = (items: Item[]): number =>
87	  items.reduce((total, item) => total + riskAdjustedPriceOf(item), 0);
88	
89	// Every group of BLOCK_SIZE alike components is priced as one discounted
90	// building block; leftovers keep their individual price.
91	const buildingBlockPriceOf = (items: Item[]): number => {
92	  const blocks = Math.floor(items.length / BLOCK_SIZE);
93	  const itemsInBlocks = blocks * BLOCK_SIZE;
94	  const leftovers = items.slice(itemsInBlocks);
95	  return blocks * BLOCK_PRICE + sumOfItemPrices(leftovers);
96	};
97	
98	const itemsPriceOf = (items: Item[]): number =>
99	  formsBuildingBlocks(items)
100	    ? buildingBlockPriceOf(items)
101	    : sumOfItemPrices(items);
102	
103	const LOYAL_YEARS = 2;
104	const LOYALTY_PERCENT = 80;
105	
106	const isLoyal = (customer: Customer): boolean =>
107	  customer.yearsWithMHPCO >= LOYAL_YEARS;
108	
109	// Premiums are always rounded up — rounding in MHPCO's favour, per spec.
110	const premiumFor = (itemsPrice: number, customer: Customer): number => {
111	  const withContractPercent = applyPercent(itemsPrice, FIRST_CONTRACT_PERCENT);
112	  const withLoyalty = isLoyal(customer)
113	    ? applyPercent(withContractPercent, LOYALTY_PERCENT)
114	    : withContractPercent;
115	  return Math.ceil(withLoyalty + CONTRACT_FEE);
116	};
117	
118	const quote = (step: Step, customer: Customer): StepResult => ({
119	  premium: premiumFor(itemsPriceOf(step.items), customer),
120	});
121	
122	export const run = (scenario: Scenario): ScenarioResult => ({
123	  results: [quote(scenario.steps[0], scenario.customer)],
124	});
