const LOYAL_YEARS = 2;
const LOYALTY_PERCENT = 80;

const isLoyal = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYAL_YEARS;

// Customer modifiers stack multiplicatively on the item price, in list order,
// the same way RISK_SURCHARGES stack on a single item's table price.
const CONTRACT_MODIFIERS: {
  applies: (customer: Customer) => boolean;
  percent: number;
}[] = [
  { applies: () => true, percent: FIRST_CONTRACT_PERCENT },
  { applies: isLoyal, percent: LOYALTY_PERCENT },
];

// Premiums are always rounded up — rounding in MHPCO's favour, per spec.
const premiumFor = (itemsPrice: number, customer: Customer): number => {
  const contractPrice = CONTRACT_MODIFIERS.filter((modifier) =>
    modifier.applies(customer),
  ).reduce(
    (price, modifier) => applyPercent(price, modifier.percent),
    itemsPrice,
  );
  return Math.ceil(contractPrice + CONTRACT_FEE);
};

